package com.portfolio.cms.controller;
import com.portfolio.cms.entity.Blog; import com.portfolio.cms.repository.BlogRepository; import jakarta.validation.Valid; import lombok.RequiredArgsConstructor; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/blogs") @RequiredArgsConstructor
public class BlogController { private final BlogRepository repo; @GetMapping public List<Blog> all(){return repo.findAll().stream().filter(Blog::isPublished).sorted(Comparator.comparing(Blog::getPublishedDate,Comparator.nullsLast(Comparator.reverseOrder()))).toList();} @GetMapping("/admin") public List<Blog> admin(){return repo.findAll();} @GetMapping("/{slug}") public Blog bySlug(@PathVariable String slug){return repo.findBySlug(slug).orElseThrow(()->new NoSuchElementException("Blog not found"));} @PostMapping public Blog create(@Valid @RequestBody Blog x){return repo.save(x);} @PutMapping("/{id}") public Blog update(@PathVariable Long id,@Valid @RequestBody Blog x){x.setId(id);return repo.save(x);} @DeleteMapping("/{id}") public void delete(@PathVariable Long id){repo.deleteById(id);} }
